def resolve(items):
    from collections import defaultdict
    import heapq

    starts = defaultdict(list)
    blackout_deltas = defaultdict(int)
    coords = set()

    for idx, (start, end, priority, name) in enumerate(items):
        if end <= start:
            continue
        coords.add(start)
        coords.add(end)
        if name.startswith("!"):
            blackout_deltas[start] += 1
            blackout_deltas[end] -= 1
        else:
            starts[start].append((-priority, idx, end, name))

    if not coords:
        return []

    heap = []
    blackout = 0
    result = []
    prev_x = None

    for x in sorted(coords):
        if prev_x is not None and blackout == 0:
            while heap and heap[0][2] <= prev_x:
                heapq.heappop(heap)
            if heap:
                name = heap[0][3]
                if result and result[-1][1] == prev_x and result[-1][2] == name:
                    result[-1] = (result[-1][0], x, name)
                else:
                    result.append((prev_x, x, name))

        if x in blackout_deltas:
            blackout += blackout_deltas[x]
        if x in starts:
            for item in starts[x]:
                heapq.heappush(heap, item)
        prev_x = x

    return result
