def resolve(items):
    events = {}
    coords = set()

    for i, (start, end, priority, name) in enumerate(items):
        if end <= start:
            continue
        coords.add(start)
        coords.add(end)
        is_blackout = -1 if name.startswith("!") else 0
        events.setdefault(start, []).append((is_blackout, -priority, i, end, name))

    if not coords:
        return []

    sorted_coords = sorted(coords)
    heap = []
    result = []

    for idx in range(len(sorted_coords) - 1):
        x = sorted_coords[idx]
        next_x = sorted_coords[idx + 1]

        for entry in events.get(x, ()):
            heapq.heappush(heap, entry)

        while heap and heap[0][3] <= x:
            heapq.heappop(heap)

        if heap and heap[0][0] == 0:
            win_name = heap[0][4]
            if result and result[-1][2] == win_name and result[-1][1] == x:
                result[-1] = (result[-1][0], next_x, win_name)
            else:
                result.append((x, next_x, win_name))

