def resolve(items):
    events = []
    normals = []
    for start, end, priority, name in items:
        if end <= start:
            continue
        if name.startswith("!"):
            events.append((start, 2, 1))
            events.append((end, 2, -1))
        else:
            idx = len(normals)
            normals.append((-priority, idx, name))
            events.append((start, 1, idx))
            events.append((end, 0, idx))

    if not events:
        return []

    events.sort()
    active = [False] * len(normals)
    heap = []
    blackout = 0
    result = []

    n = len(events)
    i = 0
    while i < n:
        x = events[i][0]
        while i < n and events[i][0] == x:
            _, kind, val = events[i]
            if kind == 2:
                blackout += val
            elif kind == 1:
                active[val] = True
                heapq.heappush(heap, normals[val])
            else:
                active[val] = False
            i += 1

        if i < n and blackout == 0:
            while heap and not active[heap[0][1]]:
                heapq.heappop(heap)
            if heap:
                next_x = events[i][0]
                name = heap[0][2]
                if result and result[-1][1] == x and result[-1][2] == name:
                    result[-1] = (result[-1][0], next_x, name)
                else:
