    result = []
    i = 0
    n = len(events)

    while i < n:
        x = events[i][0]
        while i < n and events[i][0] == x:
            _, kind, key = events[i]
            if kind == 1:
                heapq.heappush(active, key)
            i += 1

        if i == n:
            break

        next_x = events[i][0]

        while active and active[0][3] <= x:
            heapq.heappop(active)

        if active:
