                    raise ValueError(f"Invalid range syntax: {base}")
                a = parse_atom(dash_parts[0], lo, hi, names)
                b = parse_atom(dash_parts[1], lo, hi, names)
                if is_dow:
                    if a == 7 and b == 7:
