                        seq = list(range(a, b + 1))
                    else:
                        seq = list(range(a, hi + 1)) + list(range(lo, b + 1))
            else:
                a = parse_atom(base, lo, hi, names)
                if has_step:
                    if is_dow:
                        start = 0 if a == 7 else a
                        seq = list(range(start, 7))
                    else:
                        seq = list(range(a, hi + 1))
                else:
                    seq = [0 if (is_dow and a == 7) else a]

            for idx in range(0, len(seq), step):
                v = seq[idx]
                if is_dow and v == 7:
                    v = 0
                values.add(v)

        return values, has_last

    def is_restricted(field: str) -> bool:
        return not (field == "*" or field.startswith("*/"))

    minutes, _ = parse_field(min_str, 0, 59)
    hours, _ = parse_field(hour_str, 0, 23)
    doms, dom_has_last = parse_field(dom_str, 1, 31, allow_last=True)
    months, _ = parse_field(mon_str, 1, 12, names=months_map)
    dows, _ = parse_field(dow_str, 0, 7, names=dow_map, is_dow=True)

    dom_restricted = is_restricted(dom_str)
    dow_restricted = is_restricted(dow_str)

    sorted_minutes = sorted(minutes)
    sorted_hours = sorted(hours)
    sorted_months = sorted(months)

    try:
        limit = after.replace(year=after.year + 8)
    except ValueError:
        # Handle Feb 29 -> Feb 28 if target year is not a leap year (though +8 years is usually leap unless century non-leap like 2096->2104 or 2092->2100)
        limit = after.replace(year=after.year + 8, day=28)

    cur = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    def day_matches(year: int, month: int, day: int, days_in_month: int) -> bool:
        dom_ok = (day in doms) or (dom_has_last and day == days_in_month)
        # Python weekday(): Monday=0..Sunday=6 -> Cron: Sunday=0, Monday=1..Saturday=6
        cron_dow = (datetime(year, month, day).weekday() + 1) % 7
        dow_ok = cron_dow in dows

        if dom_restricted and dow_restricted:
            return dom_ok or dow_ok
        return dom_ok and dow_ok

    while cur <= limit:
        y, m = cur.year, cur.month
        if m not in months:
            next_m = next((x for x in sorted_months if x > m), None)
            if next_m is not None:
                cur = datetime(y, next_m, 1, 0, 0)
            else:
                if y + 1 > 9999:
                    return None
                cur = datetime(y + 1, sorted_months[0], 1, 0, 0)
            continue

        days_in_month = calendar.monthrange(y, m)[1]
        d = cur.day
        if not day_matches(y, m, d, days_in_month):
            if d < days_in_month:
                cur = datetime(y, m, d + 1, 0, 0)
            else:
                if m == 12:
                    if y + 1 > 9999:
                        return None
                    cur = datetime(y + 1, 1, 1, 0, 0)
                else:
                    cur = datetime(y, m + 1, 1, 0, 0)
            continue

        h = cur.hour
        if h not in hours:
            next_h = next((x for x in sorted_hours if x > h), None)
            if next_h is not None:
                cur = datetime(y, m, d, next_h, 0)
            else:
                cur = datetime(y, m, d, 0, 0) + timedelta(days=1)
            continue

        mi = cur.minute
        if mi not in minutes:
            next_mi = next((x for x in sorted_minutes if x > mi), None)
            if next_mi is not None:
                cur = datetime(y, m, d, h, next_mi)
            else:
                cur = datetime(y, m, d, h, 0) + timedelta(hours=1)
            continue

        return cur if cur <= limit else None

    return None
