from collections import defaultdict
import heapq


def resolve(items):
    class _Rev:
        __slots__ = ("v",)

        def __init__(self, v):
            self.v = v

        def __lt__(self, other):
            return other.v < self.v

    coords = set()
    starts = defaultdict(list)
    blackout_deltas = defaultdict(int)

    for idx, (start, end, priority, name) in enumerate(items):
        if end <= start:
            continue
        coords.add(start)
        coords.add(end)
        if name.startswith("!"):
            blackout_deltas[start] += 1
            blackout_deltas[end] -= 1
        else:
            key = -priority if isinstance(priority, (int, float)) else _Rev(priority)
            starts[start].append((key, idx, end, name))

    sorted_coords = sorted(coords)
    heap = []
    blackout = 0
    result = []

    for i in range(len(sorted_coords) - 1):
        x = sorted_coords[i]
        next_x = sorted_coords[i + 1]

        if x in blackout_deltas:
            blackout += blackout_deltas[x]
        if x in starts:
            for entry in starts[x]:
                heapq.heappush(heap, entry)

        if blackout == 0:
            while heap and heap[0][2] <= x:
                heapq.heappop(heap)
            if heap:
                winner_name = heap[0][3]
                if result and result[-1][1] == x and result[-1][2] == winner_name:
                    result[-1] = (result[-1][0], next_x, winner_name)
                else:
                    result.append((x, next_x, winner_name))

    return result
