                has_step = True
            else:
                base = item
                step = 1
                has_step = False

            if not base:
                raise ValueError(f"Empty base in item: {item!r}")

            if base == "*":
                seq = list(range(min_val, max_val + 1))
                values.update(seq[::step])
            elif "-" in base:
                range_parts = base.split("-")
                if len(range_parts) != 2:
