                    elif start_val <= end_val:
                        seq = list(range(start_val, end_val + 1))
                    else:
                        seq = list(range(start_val, 7)) + list(range(0, end_val + 1))
                else:
                    if start_val <= end_val:
                        seq = list(range(start_val, end_val + 1))
                    else:
                        seq = list(range(start_val, max_val + 1)) + list(range(min_val, end_val + 1))
                values.update(seq[::step])
