                if day > last_day:
                    day = 1
                    month += 1
                    if month > 12:
                        month = 1
                        year += 1
                hour = sorted_hours[0]
                minute = sorted_minutes[0]
            continue

        if minute not in minutes:
            next_minute = next((m for m in sorted_minutes if m > minute), None)
            if next_minute is not None:
