                    raise ValueError(f"Invalid step expression: {part!r}")
                base, step_str = pieces
                step = parse_uint(step_str)
                if step < 1:
                    raise ValueError(f"Step must be >= 1: {part!r}")
                has_step = True
            else:
                base = part
                step = 1
                has_step = False

            if not base:
                raise ValueError(f"Missing base before step: {part!r}")

            if base == "*":
                max_v = 6 if is_dow else hi
                seq = list(range(lo, max_v + 1))
            elif "-" in base:
                bounds = base.split("-")
                if len(bounds) != 2:
                    raise ValueError(f"Invalid range expression: {part!r}")
                a = parse_value(bounds[0], lo, hi, names)
                b = parse_value(bounds[1], lo, hi, names)
                if is_dow:
                    if a == 7 and b == 7:
                        seq = [0]
                    elif b == 7:
                        if a == 0:
                            seq = list(range(0, 7))
                        else:
                            seq = [x % 7 for x in range(a, 8)]
                    else:
                        if a == 7:
                            a = 0
                        if a <= b:
                            seq = list(range(a, b + 1))
                        else:
                            seq = list(range(a, 7)) + list(range(0, b + 1))
                else:
                    if a <= b:
                        seq = list(range(a, b + 1))
                    else:
                        seq = list(range(a, hi + 1)) + list(range(lo, b + 1))
            else:
                a = parse_value(base, lo, hi, names)
                if is_dow:
                    a = 0 if a == 7 else a
                    seq = list(range(a, 7)) if has_step else [a]
                else:
                    seq = list(range(a, hi + 1)) if has_step else [a]

            values.update(seq[::step])
        return sorted(values)

    min_raw, hour_raw, dom_raw, month_raw, dow_raw = fields

    minutes = parse_field(min_raw, 0, 59)
    hours = parse_field(hour_raw, 0, 23)
    if dom_raw == "L":
        dom_is_last = True
        dom_set = set()
    else:
        dom_is_last = False
        dom_set = set(parse_field(dom_raw, 1, 31))
    months = parse_field(month_raw, 1, 12, names=month_names)
    dow_set = set(parse_field(dow_raw, 0, 7, names=dow_names, is_dow=True))

    dom_restricted = not (dom_raw == "*" or dom_raw.startswith("*/"))
    dow_restricted = not (dow_raw == "*" or dow_raw.startswith("*/"))
    use_or = dom_restricted and dow_restricted

    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        return None

    max_year = after.year + 8
    if max_year > 9999:
        limit = datetime.max
    else:
        try:
            limit = after.replace(year=max_year)
        except ValueError:
            limit = after.replace(year=max_year, month=2, day=28)

    if start > limit:
        return None

    min_hour = hours[0]
    min_minute = minutes[0]
    start_year = start.year
    end_year = limit.year

    for year in range(start_year, end_year + 1):
        for month in months:
            if year == start_year and month < start.month:
                continue
            if year == end_year and month > limit.month:
                return None

            first_wd, last_day = calendar.monthrange(year, month)

            first_day = start.day if (year == start_year and month == start.month) else 1
            max_day = limit.day if (year == end_year and month == limit.month) else last_day
            if max_day > last_day:
                max_day = last_day

            for day in range(first_day, max_day + 1):
                dom_ok = (day == last_day) if dom_is_last else (day in dom_set)
                dow_ok = ((first_wd + day) % 7) in dow_set
                if use_or:
                    if not (dom_ok or dow_ok):
                        continue
                else:
                    if not (dom_ok and dow_ok):
                        continue

                if year == start_year and month == start.month and day == start.day:
                    cand_hour = None
                    cand_minute = None
                    for h in hours:
                        if h < start.hour:
                            continue
                        if h == start.hour:
                            for m in minutes:
