import heapq

def resolve(items):
    events = []
    for idx, (start, end, priority, name) in enumerate(items):
        if end <= start:
            continue
        is_blackout = name.startswith("!")
        events.append((start, 1, is_blackout, priority, idx, name))
        events.append((end, 0, is_blackout, priority, idx, name))

    if not events:
        return []

    events.sort(key=lambda x: x[0])

    active_heap = []
    removed = set()
    blackout_count = 0

    result = []
    n = len(events)
    i = 0

    while i < n:
        x = events[i][0]
        while i < n and events[i][0] == x:
            _, is_start, is_blackout, priority, idx, name = events[i]
            if is_blackout:
                if is_start:
                    blackout_count += 1
                else:
                    blackout_count -= 1
            else:
                if is_start:
                    heapq.heappush(active_heap, (-priority, idx, name))
                else:
                    removed.add(idx)
            i += 1

        if i < n:
            next_x = events[i][0]
            while active_heap and active_heap[0][1] in removed:
                heapq.heappop(active_heap)

            if blackout_count == 0 and active_heap:
                winner_name = active_heap[0][2]
                if result and result[-1][1] == x and result[-1][2] == winner_name:
                    result[-1] = (result[-1][0], next_x, winner_name)
                else:
                    result.append((x, next_x, winner_name))

    return result
