def resolve(items):
    import heapq
    from collections import defaultdict

    points = set()
    normal_starts = defaultdict(list)
    blackout_diff = defaultdict(int)

    for idx, (start, end, priority, name) in enumerate(items):
        if end <= start:
            continue
        points.add(start)
        points.add(end)
        if name.startswith("!"):
            blackout_diff[start] += 1
            blackout_diff[end] -= 1
        else:
            normal_starts[start].append((-priority, idx, name, end))

    sorted_points = sorted(points)
    heap = []
    blackout_count = 0
    res = []

    for i in range(len(sorted_points) - 1):
        cur_x = sorted_points[i]
        next_x = sorted_points[i + 1]

        if cur_x in blackout_diff:
            blackout_count += blackout_diff[cur_x]

        if cur_x in normal_starts:
            for item in normal_starts[cur_x]:
                heapq.heappush(heap, item)

        while heap and heap[0][3] <= cur_x:
            heapq.heappop(heap)

        if blackout_count > 0:
            winner = None
        elif heap:
            winner = heap[0][2]
        else:
            winner = None

        if winner is not None:
            if res and res[-1][2] == winner and res[-1][1] == cur_x:
                res[-1] = (res[-1][0], next_x, winner)
            else:
                res.append((cur_x, next_x, winner))

    return res
