        low = tok.lower()
        if names and low in names:
            return names[low]
        try:
            val = int(tok)
        except ValueError as exc:
            raise ValueError(f"Invalid token: {tok}") from exc
        if val < min_val or val > max_val:
            raise ValueError(f"Value {val} out of range [{min_val}, {max_val}]")
        return val

    def parse_field(field_str, min_val, max_val, names=None, is_dow=False):
