                            seq = list(range(s, 7)) + list(range(0, e + 1))
                    else:
                        seq = list(range(start, max_val + 1)) + list(range(min_val, end + 1))
            else:
                val = parse_token(base, min_val, max_val, names)
                if "/" in item:
                    seq = list(range(val, max_val + 1))
                else:
                    seq = [val]

            for v in seq[::step]:
                result.add(0 if (is_dow and v == 7) else v)

        return result

