def resolve(items):
    import heapq

    events = []
    for idx, (start, end, priority, name) in enumerate(items):
        if end <= start:
            continue
        if name.startswith("!"):
            events.append((start, 0, 1))
            events.append((end, 0, -1))
        else:
            events.append((start, 1, (-priority, idx, end, name)))
            events.append((end, 2, None))

    events.sort(key=lambda e: e[0])

    result = []
    heap = []
    blackout = 0
    n = len(events)
    i = 0

    while i < n:
        x = events[i][0]
        while i < n and events[i][0] == x:
            _, kind, payload = events[i]
            if kind == 0:
                blackout += payload
            elif kind == 1:
                heapq.heappush(heap, payload)
            i += 1

        if i == n:
            break

        next_x = events[i][0]
        if blackout == 0:
            while heap and heap[0][2] <= x:
                heapq.heappop(heap)
            if heap:
                winner = heap[0][3]
                if result and result[-1][1] == x and result[-1][2] == winner:
                    result[-1] = (result[-1][0], next_x, winner)
                else:
                    result.append((x, next_x, winner))

    return result
