                if len(subparts) != 2:
                    raise ValueError(f"Invalid step syntax: {part}")
                base, step_str = subparts
                if not step_str.isdigit():
                    raise ValueError(f"Invalid step value: {step_str}")
                step = int(step_str)
                if step <= 0:
                    raise ValueError(f"Step must be positive: {step}")
            else:
                base = part
                step = None

            if base == "*":
                if is_dow:
                    seq = list(range(0, 8))
                else:
