                    return None
                current = datetime(current.year + 1, 1, 1, 0, 0)
            else:
                current = datetime(current.year, current.month + 1, 1, 0, 0)
            continue

        max_days = calendar.monthrange(current.year, current.month)[1]
        if is_dom_l:
            day_in_dom = current.day == max_days
        else:
            day_in_dom = current.day in valid_doms

        cron_dow = (current.weekday() + 1) % 7
        day_in_dow = cron_dow in valid_dows

        if dom_restricted and dow_restricted:
            day_matches = day_in_dom or day_in_dow
        else:
            day_matches = day_in_dom and day_in_dow

        if not day_matches:
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        if current.hour not in valid_hours:
            current = (current + timedelta(hours=1)).replace(minute=0)
            continue

        if current.minute not in valid_mins:
            current += timedelta(minutes=1)
            continue

        return current

    return None
