                    raise ValueError(f"Invalid range: {base!r}")
                raw_a = parse_value(dash_parts[0], min_val, max_val, names)
                raw_b = parse_value(dash_parts[1], min_val, max_val, names)
                if is_dow:
                    a = 0 if raw_a == 7 else raw_a
                    if raw_a == 7 and raw_b == 7:
                        seq = [0]
                    elif raw_b == 7:
                        seq = [x % 7 for x in range(a, 8)]
                    elif a <= raw_b:
                        seq = list(range(a, raw_b + 1))
                    else:
                        seq = list(range(a, 7)) + list(range(0, raw_b + 1))
                else:
                    if raw_a <= raw_b:
                        seq = list(range(raw_a, raw_b + 1))
                    else:
                        seq = list(range(raw_a, max_val + 1)) + list(range(min_val, raw_b + 1))
            else:
                val = parse_value(base, min_val, max_val, names)
                if has_step:
                    if is_dow:
                        a = 0 if val == 7 else val
                        seq = list(range(a, 7))
                    else:
                        seq = list(range(val, max_val + 1))
                else:
                    seq = [0 if (is_dow and val == 7) else val]

            values.update(seq[::step])

        if not values:
            raise ValueError(f"Empty field: {field!r}")
        return values

    min_field, hour_field, dom_field, mon_field, dow_field = fields

    minutes = sorted(parse_field(min_field, 0, 59))
    hours = sorted(parse_field(hour_field, 0, 23))
    months = sorted(parse_field(mon_field, 1, 12, names=month_names))

    dom_is_last = dom_field == "L"
    dom_vals = set() if dom_is_last else parse_field(dom_field, 1, 31)
    dow_vals = parse_field(dow_field, 0, 7, names=dow_names, is_dow=True)

    dom_restricted = not (dom_field == "*" or dom_field.startswith("*/"))
    dow_restricted = not (dow_field == "*" or dow_field.startswith("*/"))

    def day_matches(year, month, day, last_day):
        dom_ok = (day == last_day) if dom_is_last else (day in dom_vals)
        dow = (datetime(year, month, day).weekday() + 1) % 7
        dow_ok = dow in dow_vals
        if dom_restricted and dow_restricted:
            return dom_ok or dow_ok
        return dom_ok and dow_ok

    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        return None

    if after.year + 8 > datetime.max.year:
        limit = datetime.max
    else:
        try:
            limit = after.replace(year=after.year + 8)
        except ValueError:
            limit = after.replace(year=after.year + 8, day=28)

    year, month, day, hour, minute = (
        start.year, start.month, start.day, start.hour, start.minute
    )

    while year <= limit.year:
        next_month = next((m for m in months if m >= month), None)
        if next_month is None:
            year += 1
            month = months[0]
            day = 1
            hour = hours[0]
            minute = minutes[0]
            continue
        if next_month > month:
            month = next_month
            day = 1
            hour = hours[0]
            minute = minutes[0]

        last_day = calendar.monthrange(year, month)[1]
        next_day = next(
            (d for d in range(day, last_day + 1) if day_matches(year, month, d, last_day)),
            None,
        )
        if next_day is None:
            month += 1
            if month > 12:
                year += 1
                month = 1
            day = 1
            hour = hours[0]
            minute = minutes[0]
            continue
        if next_day > day:
            day = next_day
            hour = hours[0]
            minute = minutes[0]

        next_hour = next((h for h in hours if h >= hour), None)
        if next_hour is None:
            day += 1
            hour = hours[0]
            minute = minutes[0]
            continue
        if next_hour > hour:
            hour = next_hour
            minute = minutes[0]

        next_minute = next((mi for mi in minutes if mi >= minute), None)
        if next_minute is None:
            hour += 1
            minute = minutes[0]
            if hour > 23:
                hour = hours[0]
                day += 1
            continue

        candidate = datetime(year, month, day, hour, next_minute)
        return candidate if candidate <= limit else None

    return None
