    if not stripped:
        raise ValueError("Empty cron expression")

    fields = []
    buf = []
    for ch in stripped:
        if ch in (" ", "\t"):
            if buf:
                fields.append("".join(buf))
                buf = []
        else:
            buf.append(ch)
    if buf:
        fields.append("".join(buf))
    if len(fields) != 5:
        raise ValueError("Expected 5 fields in cron expression")

    month_names = {
        "jan": 1, "feb": 2, "mar": 3, "apr": 4,
        "may": 5, "jun": 6, "jul": 7, "aug": 8,
        "sep": 9, "oct": 10, "nov": 11, "dec": 12,
    }
    dow_names = {
        "sun": 0, "mon": 1, "tue": 2, "wed": 3,
        "thu": 4, "fri": 5, "sat": 6,
    }

    def parse_atom(token, min_val, max_val, names):
        if not token:
            raise ValueError("Empty value")
        if names is not None:
            low = token.lower()
            if low in names:
                val = names[low]
                if min_val <= val <= max_val:
                    return val
                raise ValueError("Value out of range")
        if not (token.isascii() and token.isdigit()):
            raise ValueError(f"Invalid token: {token!r}")
        val = int(token)
        if val < min_val or val > max_val:
            raise ValueError(f"Value out of range: {val}")
        return val

    def parse_field(field_str, min_val, max_val, wrap_max, names=None, is_dow=False):
        result = set()
        for part in field_str.split(","):
            if not part:
                raise ValueError("Empty list item")
            if "/" in part:
                slash_parts = part.split("/")
                if len(slash_parts) != 2:
                    raise ValueError("Invalid step syntax")
                base, step_str = slash_parts
                if not (step_str and step_str.isascii() and step_str.isdigit()):
                    raise ValueError("Invalid step value")
                step = int(step_str)
                if step <= 0:
                    raise ValueError("Step must be positive")
            else:
                base = part
                step = None

            if not base:
                raise ValueError("Missing base before step")

            if base == "*":
                s = 1 if step is None else step
                seq = range(min_val, wrap_max + 1, s)
            elif "-" in base:
                dash_parts = base.split("-")
                if len(dash_parts) != 2:
                    raise ValueError("Invalid range syntax")
                a_str, b_str = dash_parts
                a = parse_atom(a_str, min_val, max_val, names)
                b = parse_atom(b_str, min_val, max_val, names)
                if is_dow and a == 7 and b != 7:
                    raise ValueError("Invalid day-of-week range starting with 7")
                s = 1 if step is None else step
                if a <= b:
                    seq = range(a, b + 1, s)
                else:
                    seq = (list(range(a, wrap_max + 1)) + list(range(min_val, b + 1)))[::s]
            else:
                a = parse_atom(base, min_val, max_val, names)
                if step is None:
                    seq = (a,)
                else:
                    seq = range(a, max_val + 1, step)

            if is_dow:
                for x in seq:
                    result.add(x % 7)
            else:
                result.update(seq)
        return sorted(result)

    min_str, hour_str, dom_str, month_str, dow_str = fields

    minutes = parse_field(min_str, 0, 59, 59)
    hours = parse_field(hour_str, 0, 23, 23)
    if dom_str == "L":
        dom_is_last = True
        dom_set = set()
    else:
        dom_is_last = False
        dom_set = set(parse_field(dom_str, 1, 31, 31))
    months_set = set(parse_field(month_str, 1, 12, 12, names=month_names))
    dow_set = set(parse_field(dow_str, 0, 7, 6, names=dow_names, is_dow=True))

    if not isinstance(after, datetime) or after.tzinfo is not None:
        raise ValueError("after must be a naive datetime")

    dom_restricted = not (dom_str == "*" or dom_str.startswith("*/"))
    dow_restricted = not (dow_str == "*" or dow_str.startswith("*/"))
    both_restricted = dom_restricted and dow_restricted

    try:
        limit = after.replace(year=after.year + 8)
    except ValueError:
        if after.year + 8 > datetime.max.year:
            limit = datetime.max
        else:
            limit = after.replace(year=after.year + 8, day=28)

    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        return None

    if start > limit:
        return None

    y, m, start_d = start.year, start.month, start.day
    is_start_month = True
    limit_ym = (limit.year, limit.month)

    while (y, m) <= limit_ym:
        if m in months_set:
            first_wd, days_in_month = calendar.monthrange(y, m)
            max_d = limit.day if (y, m) == limit_ym else days_in_month
            for d in range(start_d, max_d + 1):
                dom_ok = (d == days_in_month) if dom_is_last else (d in dom_set)
                dow_ok = ((first_wd + d) % 7) in dow_set
                day_ok = (dom_ok or dow_ok) if both_restricted else (dom_ok and dow_ok)
                if day_ok:
                    if is_start_month and d == start.day:
                        found_hm = None
                        for h in hours:
                            if h < start.hour:
                                continue
                            if h == start.hour:
                                for mn in minutes:
                                    if mn >= start.minute:
                                        found_hm = (h, mn)
                                        break
                                if found_hm is not None:
                                    break
                            else:
                                found_hm = (h, minutes[0])
                                break
                        if found_hm is not None:
                            cand = datetime(y, m, d, found_hm[0], found_hm[1])
                            return cand if cand <= limit else None
                    else:
                        cand = datetime(y, m, d, hours[0], minutes[0])
                        return cand if cand <= limit else None
        is_start_month = False
        start_d = 1
        if m == 12:
            y += 1
            m = 1
        else:
            m += 1

    return None
