import calendar
from datetime import datetime, timedelta


def next_run(expr: str, after: datetime) -> datetime | None:
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")
    if not isinstance(after, datetime) or after.tzinfo is not None:
        raise ValueError("after must be a naive datetime")

    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    MONTH_NAMES = {
        "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
        "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12
    }
    DOW_NAMES = {
        "sun": 0, "mon": 1, "tue": 2, "wed": 3, "thu": 4, "fri": 5, "sat": 6
    }

    def parse_atom(s: str, low: int, high: int, names: dict[str, int] | None) -> int:
        if not s:
            raise ValueError("Empty value")
        sl = s.lower()
        if names and sl in names:
            return names[sl]
        if not (s.isdigit() and s.isascii()):
            raise ValueError(f"Invalid value: {s}")
        val = int(s)
        if val < low or val > high:
            raise ValueError(f"Value {val} out of bounds [{low}, {high}]")
        return val

    def parse_field(
        field_str: str,
        low: int,
        high: int,
        names: dict[str, int] | None = None,
        is_dom: bool = False,
        is_dow: bool = False,
    ) -> tuple[set[int], bool]:
        if not field_str:
            raise ValueError("Empty field")
        parts = field_str.split(",")
        values: set[int] = set()
        has_L = False

        for part in parts:
            if not part:
                raise ValueError("Empty list element")

            if is_dom and part.upper() == "L":
                has_L = True
                continue

            if "/" in part:
                subparts = part.split("/")
                if len(subparts) != 2:
                    raise ValueError(f"Invalid step syntax: {part}")
                base, step_str = subparts
                if not (step_str.isdigit() and step_str.isascii()):
                    raise ValueError(f"Invalid step value: {step_str}")
                step = int(step_str)
                if step <= 0:
                    raise ValueError("Step must be positive")
            else:
                base = part
                step = None

            if base == "*":
                seq = list(range(low, 7 if is_dow else high + 1))
            elif "-" in base:
                rparts = base.split("-")
                if len(rparts) != 2:
                    raise ValueError(f"Invalid range syntax: {base}")
                a = parse_atom(rparts[0], low, high, names)
                b = parse_atom(rparts[1], low, high, names)
                if a <= b:
                    seq = list(range(a, b + 1))
                else:
                    if is_dow:
                        a_norm = 0 if a == 7 else a
                        b_norm = 0 if b == 7 else b
                        if a_norm <= b_norm:
                            seq = list(range(a_norm, b_norm + 1))
                        else:
                            seq = list(range(a_norm, 7)) + list(range(0, b_norm + 1))
                    else:
                        seq = list(range(a, high + 1)) + list(range(low, b + 1))
            else:
                a = parse_atom(base, low, high, names)
                if step is None:
                    seq = [a]
                else:
                    if is_dow:
                        seq = [0] if a == 7 else list(range(a, 7))
                    else:
                        seq = list(range(a, high + 1))

            if step is not None:
                seq = seq[::step]

            if is_dow:
                for v in seq:
                    values.add(0 if v == 7 else v)
            else:
                values.update(seq)

        return values, has_L

    min_f, hour_f, dom_f, month_f, dow_f = fields

    minutes, _ = parse_field(min_f, 0, 59)
    hours, _ = parse_field(hour_f, 0, 23)
    doms, dom_has_L = parse_field(dom_f, 1, 31, is_dom=True)
    months, _ = parse_field(month_f, 1, 12, names=MONTH_NAMES)
    dows, _ = parse_field(dow_f, 0, 7, names=DOW_NAMES, is_dow=True)

    dom_restricted = not (dom_f == "*" or dom_f.startswith("*/"))
    dow_restricted = not (dow_f == "*" or dow_f.startswith("*/"))

    def day_matches(year: int, month: int, day: int) -> bool:
        last_day = calendar.monthrange(year, month)[1]
        dom_match = (day in doms) or (dom_has_L and day == last_day)
        # Python weekday(): Monday is 0 ... Sunday is 6 -> cron: Sunday is 0 ... Saturday is 6
        cron_dow = (datetime(year, month, day).weekday() + 1) % 7
        dow_match = cron_dow in dows

        if dom_restricted and dow_restricted:
            return dom_match or dow_match
        return dom_match and dow_match

    sorted_months = sorted(months)
    sorted_hours = sorted(hours)
    sorted_minutes = sorted(minutes)

    if not sorted_months or not sorted_hours or not sorted_minutes or (not doms and not dom_has_L) or not dows:
        return None

    try:
        limit = after.replace(year=after.year + 8)
    except ValueError:
        # e.g., if after were Feb 29 and after.year + 8 were not a leap year (though +8 is always leap except across non-leap centuries)
        limit = after.replace(year=after.year + 8, day=28) + timedelta(days=1)

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    if start > limit:
        return None

    cur_year = start.year
    max_year = limit.year

    while cur_year <= max_year:
        for m in sorted_months:
            if cur_year == start.year and m < start.month:
                continue
            if cur_year == max_year and m > limit.month:
                return None

            last_day = calendar.monthrange(cur_year, m)[1]
            start_day = start.day if (cur_year == start.year and m == start.month) else 1

            for d in range(start_day, last_day + 1):
                if cur_year == max_year and m == limit.month and d > limit.day:
                    return None
                if not day_matches(cur_year, m, d):
                    continue

                is_start_day = (cur_year == start.year and m == start.month and d == start.day)
                for h in sorted_hours:
                    if is_start_day and h < start.hour:
                        continue

                    is_start_hour = is_start_day and (h == start.hour)
                    for mi in sorted_minutes:
                        if is_start_hour and mi < start.minute:
                            continue

                        candidate = datetime(cur_year, m, d, h, mi, 0, 0)
                        if candidate <= limit:
                            return candidate
                        return None
        cur_year += 1

    return None
