def resolve(items):
    import heapq

    events = []
    for idx, (start, end, priority, name) in enumerate(items):
        if end <= start:
            continue
        if name.startswith("!"):
            events.append((start, 1, None))
            events.append((end, -1, None))
        else:
            events.append((start, 0, (-priority, idx, end, name)))
            events.append((end, 0, None))

    events.sort(key=lambda e: e[0])

    heap = []
    blackout = 0
    res = []
    i = 0
    n = len(events)

    while i < n:
        x = events[i][0]
        while i < n and events[i][0] == x:
            _, blk, entry = events[i]
            blackout += blk
            if entry is not None:
                heapq.heappush(heap, entry)
            i += 1
        if i == n:
            break
        next_x = events[i][0]
        while heap and heap[0][2] <= x:
            heapq.heappop(heap)
        if blackout == 0 and heap:
            winner = heap[0][3]
            if res and res[-1][1] == x and res[-1][2] == winner:
                res[-1] = (res[-1][0], next_x, winner)
            else:
                res.append((x, next_x, winner))

    return res
