        dom_set = None
    else:
        dom_is_last = False
        dom_set = set(parse_field(dom_str, 1, 31))
    months = parse_field(month_str, 1, 12, month_names)
    dow_set = set(parse_field(dow_str, 0, 7, dow_names, is_dow=True))

    dom_restricted = not (dom_str == "*" or dom_str.startswith("*/"))
    dow_restricted = not (dow_str == "*" or dow_str.startswith("*/"))
    either_day = dom_restricted and dow_restricted

    min_minute, max_minute = minutes[0], minutes[-1]
    min_hour, max_hour = hours[0], hours[-1]
    min_month, max_month = months[0], months[-1]

    try:
        cur = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        return None

    if after.year + 8 > 9999:
        limit = datetime.max
    else:
        try:
            limit = after.replace(year=after.year + 8)
        except ValueError:
            limit = after.replace(year=after.year + 8, day=28)

    limit_year = limit.year
    year, month, day, hour, minute = cur.year, cur.month, cur.day, cur.hour, cur.minute

    while year <= limit_year:
        if month > max_month:
            year += 1
            month = min_month
            day = 1
            hour = min_hour
            minute = min_minute
            continue
        next_month = next(m for m in months if m >= month)
        if next_month != month:
            month = next_month
            day = 1
            hour = min_hour
            minute = min_minute

        days_in_month = calendar.monthrange(year, month)[1]
        day_found = False
        while day <= days_in_month:
            dom_ok = (day == days_in_month) if dom_is_last else (day in dom_set)
            dow_ok = ((calendar.weekday(year, month, day) + 1) % 7) in dow_set
            day_ok = (dom_ok or dow_ok) if either_day else (dom_ok and dow_ok)
            if day_ok:
                day_found = True
                break
            day += 1
            hour = min_hour
            minute = min_minute

        if not day_found:
            month += 1
            day = 1
            hour = min_hour
            minute = min_minute
            continue

        if hour > max_hour:
            day += 1
            hour = min_hour
            minute = min_minute
            continue
        next_hour = next(h for h in hours if h >= hour)
        if next_hour != hour:
            hour = next_hour
            minute = min_minute

        if minute > max_minute:
            hour += 1
            minute = min_minute
            continue
        minute = next(m for m in minutes if m >= minute)

        candidate = datetime(year, month, day, hour, minute)
        if candidate > limit:
            return None
        return candidate

    return None
