import calendar
from datetime import datetime, timedelta


def next_run(expr: str, after: datetime) -> datetime | None:
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")
    if not isinstance(after, datetime) or after.tzinfo is not None:
        raise ValueError("after must be a naive datetime")

    fields = expr.strip().split()
    if len(fields) != 5 or any(not f for f in fields):
        raise ValueError("Cron expression must have exactly 5 fields")

    MONTHS = {
        "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
        "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
    }
    WEEKDAYS = {
        "sun": 0, "mon": 1, "tue": 2, "wed": 3, "thu": 4, "fri": 5, "sat": 6,
    }

    def parse_atom(token: str, min_val: int, max_val: int, names: dict[str, int] | None) -> int:
        if not token:
            raise ValueError("Empty value")
        low = token.lower()
        if names and low in names:
            return names[low]
        if not token.isascii() or not token.isdigit():
            raise ValueError(f"Invalid value: {token}")
        val = int(token)
        if val < min_val or val > max_val:
            raise ValueError(f"Value {val} out of range [{min_val}, {max_val}]")
        return val

    def parse_field(
        field_str: str,
        min_val: int,
        max_val: int,
        names: dict[str, int] | None = None,
        allow_l: bool = False,
        is_dow: bool = False,
    ) -> tuple[set[int], bool]:
        if not field_str:
            raise ValueError("Empty field")
        parts = field_str.split(",")
        if any(not p for p in parts):
            raise ValueError(f"Empty list item in field: {field_str}")

        values: set[int] = set()
        has_l = False

        for part in parts:
            if allow_l and part.upper() == "L":
                has_l = True
                continue

            if "/" in part:
                if part.count("/") > 1:
                    raise ValueError(f"Invalid step syntax: {part}")
                base, step_str = part.split("/")
                if not step_str or not step_str.isascii() or not step_str.isdigit():
                    raise ValueError(f"Invalid step: {step_str}")
                step = int(step_str)
                if step <= 0:
                    raise ValueError("Step must be positive")
                has_step = True
            else:
                base = part
                step = 1
                has_step = False

            if base == "*":
                seq = list(range(min_val, (6 if is_dow else max_val) + 1))
            elif "-" in base:
                if base.count("-") > 1:
                    raise ValueError(f"Invalid range: {base}")
                a_str, b_str = base.split("-")
                a = parse_atom(a_str, min_val, max_val, names)
                b = parse_atom(b_str, min_val, max_val, names)
                if is_dow:
                    if a == b:
                        seq = [0 if a == 7 else a]
                    else:
                        a_norm = 0 if a == 7 else a
                        b_norm = 0 if b == 7 else b
                        if a_norm == b_norm:
                            # 0-7 or 7-0: full week 0..6 (plus trailing Sunday if 0-7? Wait: 0 to 7 is 8 items 0,1,2,3,4,5,6,7)
                            if a == 0 and b == 7:
                                seq = [0, 1, 2, 3, 4, 5, 6, 7]
                            else:
                                # 7-0 wraps from Sunday(7->0) around to Sunday(0): 7,1,2,3,4,5,6,0
                                seq = [0, 1, 2, 3, 4, 5, 6, 0]
                        elif a <= b:
                            seq = list(range(a, b + 1))
                        else:
                            # Wrap around modularly on 7-day cycle (0..6)
                            seq = list(range(a_norm, 7)) + list(range(0, b_norm + 1))
                else:
                    if a <= b:
                        seq = list(range(a, b + 1))
                    else:
                        seq = list(range(a, max_val + 1)) + list(range(min_val, b + 1))
            else:
                a = parse_atom(base, min_val, max_val, names)
                if has_step:
                    if is_dow:
                        a_norm = 0 if a == 7 else a
                        seq = list(range(a_norm, 7))
                    else:
                        seq = list(range(a, max_val + 1))
                else:
                    seq = [a]

            for v in seq[::step]:
                if is_dow and v == 7:
                    values.add(0)
                else:
                    values.add(v)

        return values, has_l

    def is_restricted(field_str: str) -> bool:
        return not (field_str == "*" or field_str.startswith("*/"))

    min_str, hour_str, dom_str, mon_str, dow_str = fields

    minutes, _ = parse_field(min_str, 0, 59)
    hours, _ = parse_field(hour_str, 0, 23)
    doms, dom_has_l = parse_field(dom_str, 1, 31, allow_l=True)
    months, _ = parse_field(mon_str, 1, 12, names=MONTHS)
    dows, _ = parse_field(dow_str, 0, 7, names=WEEKDAYS, is_dow=True)

    dom_restricted = is_restricted(dom_str)
    dow_restricted = is_restricted(dow_str)

    sorted_minutes = sorted(minutes)
    sorted_hours = sorted(hours)
    sorted_months = sorted(months)

    try:
        limit = after.replace(year=after.year + 8)
    except ValueError:
        # Feb 29 -> Feb 28 (though +8 years from a leap year is normally a leap year, except century non-leaps like 2096->2104, or 2092->2100!)
        limit = after.replace(year=after.year + 8, day=28)

    # Start candidate strictly after `after`, with seconds and microseconds zero
    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    if start > limit:
        return None

    def day_matches(year: int, month: int, day: int, last_day: int) -> bool:
        dom_match = (day in doms) or (dom_has_l and day == last_day)
        # Python weekday(): Monday=0..Sunday=6 -> cron: Sunday=0, Monday=1..Saturday=6
        cron_dow = (datetime(year, month, day).weekday() + 1) % 7
        dow_match = cron_dow in dows

        if dom_restricted and dow_restricted:
            return dom_match or dow_match
        return dom_match and dow_match

    y = start.year
    max_year = limit.year

    while y <= max_year:
        for m in sorted_months:
            if y == start.year and m < start.month:
                continue
            if y == max_year and m > limit.month:
                return None

            last_day = calendar.monthrange(y, m)[1]
            d_start = start.day if (y == start.year and m == start.month) else 1

            for d in range(d_start, last_day + 1):
                if y == max_year and m == limit.month and d > limit.day:
                    return None
                if not day_matches(y, m, d, last_day):
                    continue

                is_start_day = (y == start.year and m == start.month and d == start.day)
                for h in sorted_hours:
                    if is_start_day and h < start.hour:
                        continue
                    is_start_hour = is_start_day and (h == start.hour)
                    for mn in sorted_minutes:
                        if is_start_hour and mn < start.minute:
                            continue
                        candidate = datetime(y, m, d, h, mn, 0, 0)
                        if candidate > limit:
                            return None
                        return candidate
        y += 1

    return None
