    blackout_count = 0
    result = []

    for i in range(len(coords) - 1):
        cur_x = coords[i]
        next_x = coords[i + 1]

        if cur_x in blackout_delta:
            blackout_count += blackout_delta[cur_x]

        if cur_x in starts:
            for item in starts[cur_x]:
                heapq.heappush(heap, item)

        while heap and heap[0][2] <= cur_x:
            heapq.heappop(heap)

        if blackout_count > 0 or not heap:
            winner = None
        else:
            winner = heap[0][3]

        if winner is not None:
            if result and result[-1][2] == winner and result[-1][1] == cur_x:
                result[-1] = (result[-1][0], next_x, winner)
            else:
                result.append((cur_x, next_x, winner))

