from datetime import datetime, timedelta


def next_run(expr, after):
    if not isinstance(expr, str) or any(ch in expr for ch in "\n\r\v\f"):
        raise ValueError("Invalid cron expression")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    month_names = {
        "jan": 1, "feb": 2, "mar": 3, "apr": 4,
        "may": 5, "jun": 6, "jul": 7, "aug": 8,
        "sep": 9, "oct": 10, "nov": 11, "dec": 12,
    }
    dow_names = {
        "sun": 0, "mon": 1, "tue": 2, "wed": 3,
        "thu": 4, "fri": 5, "sat": 6,
    }

    def parse_uint(token):
        if not token or not token.isascii() or not token.isdecimal():
            raise ValueError(f"Invalid integer: {token!r}")
        return int(token)

    def parse_atom(token, min_val, max_val, names):
        if names is not None:
            mapped = names.get(token.lower())
            if mapped is not None:
                return mapped
        val = parse_uint(token)
        if val < min_val or val > max_val:
            raise ValueError(f"Value out of range: {token!r}")
        return val

    def parse_field(field_str, min_val, max_val, names=None, is_dow=False):
        if not field_str:
            raise ValueError("Empty field")
        values = set()
        for item in field_str.split(","):
            if not item:
                raise ValueError(f"Empty item in field: {field_str!r}")
            if "/" in item:
                parts = item.split("/")
                if len(parts) != 2 or not parts[0] or not parts[1]:
                    raise ValueError(f"Invalid step expression: {item!r}")
                base, step_str = parts
                step = parse_uint(step_str)
                if step == 0:
                    raise ValueError("Step cannot be zero")
            else:
                base = item
                step = None

            if base == "*":
                values.update(range(min_val, max_val + 1, step or 1))
            elif "-" in base:
                bounds = base.split("-")
                if len(bounds) != 2 or not bounds[0] or not bounds[1]:
                    raise ValueError(f"Invalid range expression: {item!r}")
                start_val = parse_atom(bounds[0], min_val, max_val, names)
                end_max = 7 if is_dow else max_val
                end_val = parse_atom(bounds[1], min_val, end_max, names)
                if start_val <= end_val:
                    seq = list(range(start_val, end_val + 1))
                else:
                    seq = list(range(start_val, max_val + 1)) + list(range(min_val, end_val + 1))
                if step is not None:
                    seq = seq[::step]
                if is_dow:
                    values.update(v % 7 for v in seq)
                else:
                    values.update(seq)
            else:
                if step is None:
                    atom_max = 7 if is_dow else max_val
                    val = parse_atom(base, min_val, atom_max, names)
                    values.add(val % 7 if is_dow else val)
                else:
                    start_val = parse_atom(base, min_val, max_val, names)
                    values.update(range(start_val, max_val + 1, step))
        return sorted(values)

    min_str, hour_str, dom_str, month_str, dow_str = fields

    minutes = parse_field(min_str, 0, 59)
    hours = parse_field(hour_str, 0, 23)
    if dom_str == "L":
        dom_is_last = True
        dom_set = None
    else:
        dom_is_last = False
        dom_set = set(parse_field(dom_str, 1, 31))
    months = parse_field(month_str, 1, 12, names=month_names)
    dow_set = set(parse_field(dow_str, 0, 6, names=dow_names, is_dow=True))

    dom_restricted = not (dom_str == "*" or dom_str.startswith("*/"))
    dow_restricted = not (dow_str == "*" or dow_str.startswith("*/"))
    both_restricted = dom_restricted and dow_restricted

    if after.year + 8 > 9999:
        limit = datetime.max
    else:
        try:
            limit = after.replace(year=after.year + 8)
        except ValueError:
            limit = after.replace(year=after.year + 8, day=28)

    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        return None

    if start > limit:
        return None

    for year in range(start.year, limit.year + 1):
        for month in months:
            if year == start.year and month < start.month:
                continue
            if year == limit.year and month > limit.month:
                return None

            first_wd, num_days = calendar.monthrange(year, month)
            first_day = start.day if (year == start.year and month == start.month) else 1

            for day in range(first_day, num_days + 1):
                if year == limit.year and month == limit.month and day > limit.day:
                    return None

                dom_ok = (day == num_days) if dom_is_last else (day in dom_set)
                dow_ok = ((first_wd + day) % 7) in dow_set
                if not ((dom_ok or dow_ok) if both_restricted else (dom_ok and dow_ok)):
                    continue

                if year == start.year and month == start.month and day == start.day:
                    for h in hours:
                        if h < start.hour:
                            continue
                        if h == start.hour:
                            for m in minutes:
                                if m >= start.minute:
                                    dt = datetime(year, month, day, h, m)
                                    return dt if dt <= limit else None
                        else:
                            dt = datetime(year, month, day, h, minutes[0])
                            return dt if dt <= limit else None
                else:
                    dt = datetime(year, month, day, hours[0], minutes[0])
                    return dt if dt <= limit else None

    return None
