def resolve(items):
    from heapq import heappop, heappush

    class _Entry:
        __slots__ = ("p", "i", "end", "name")

        def __init__(self, p, i, end, name):
            self.p = p
            self.i = i
            self.end = end
            self.name = name

        def __lt__(self, other):
            if self.p == other.p:
                return self.i < other.i
            return self.p > other.p

    coord_set = set()
    blackout_diff = {}
    starts = {}

    for idx, (start, end, priority, name) in enumerate(items):
        if end <= start:
            continue
        coord_set.add(start)
        coord_set.add(end)
        if name.startswith("!"):
            blackout_diff[start] = blackout_diff.get(start, 0) + 1
            blackout_diff[end] = blackout_diff.get(end, 0) - 1
        else:
            starts.setdefault(start, []).append(_Entry(priority, idx, end, name))

    if not starts:
        return []

    coords = sorted(coord_set)
    heap = []
    blackout_count = 0
    result = []

    for k in range(len(coords) - 1):
        x = coords[k]
        next_x = coords[k + 1]

        blackout_count += blackout_diff.get(x, 0)

        if x in starts:
            for entry in starts[x]:
                heappush(heap, entry)

        while heap and heap[0].end <= x:
            heappop(heap)

        if blackout_count == 0 and heap:
            win_name = heap[0].name
            if result and result[-1][1] == x and result[-1][2] == win_name:
                result[-1] = (result[-1][0], next_x, win_name)
            else:
                result.append((x, next_x, win_name))

    return result
