            raise ValueError(f"Invalid integer: {token!r}")
        return int(token)

    def parse_atom(token, lo, hi, names=None, allow_seven=False):
        if not token:
            raise ValueError("Empty value")
        if names is not None:
            low = token.lower()
            if low in names:
                return names[low]
        val = parse_uint(token)
        max_v = 7 if allow_seven else hi
        if val < lo or val > max_v:
            raise ValueError(f"Value {val} out of range [{lo}, {max_v}]")
        return val

    def parse_field(field, lo, hi, names=None, is_dow=False):
        if not field:
            raise ValueError("Empty field")
        values = set()
        for part in field.split(","):
            if not part:
                raise ValueError(f"Empty list item in field {field!r}")
            if "/" in part:
                slash_parts = part.split("/")
                if len(slash_parts) != 2:
                    raise ValueError(f"Invalid step syntax in {part!r}")
                base, step_str = slash_parts
                step = parse_uint(step_str)
                if step <= 0:
                    raise ValueError(f"Step must be positive in {part!r}")
                has_step = True
            else:
                base = part
                step = 1
                has_step = False

            if base == "*":
                seq = list(range(lo, hi + 1))
            elif "-" in base:
                dash_parts = base.split("-")
                if len(dash_parts) != 2:
                    raise ValueError(f"Invalid range syntax in {part!r}")
                a = parse_atom(dash_parts[0], lo, hi, names, allow_seven=is_dow)
                b = parse_atom(dash_parts[1], lo, hi, names, allow_seven=is_dow)
                if is_dow:
                    if a == 7:
                        a = 0
                        if b == 7:
                            b = 0
                    if b == 7:
                        seq = list(range(a, 8))
                    elif a <= b:
                        seq = list(range(a, b + 1))
                    else:
                        seq = list(range(a, hi + 1)) + list(range(lo, b + 1))
                else:
                    if a <= b:
                        seq = list(range(a, b + 1))
                    else:
                        seq = list(range(a, hi + 1)) + list(range(lo, b + 1))
            else:
                a = parse_atom(base, lo, hi, names, allow_seven=is_dow)
                if is_dow and a == 7:
                    a = 0
                if has_step:
                    seq = list(range(a, hi + 1))
                else:
                    seq = [a]

            for v in seq[::step]:
                values.add(v % 7 if is_dow else v)

        if not values:
            raise ValueError(f"Field {field!r} matched no values")
        return values

    minutes = sorted(parse_field(min_field, 0, 59))
    hours = sorted(parse_field(hour_field, 0, 23))
    dom_is_last = dom_field == "L"
    dom_set = None if dom_is_last else parse_field(dom_field, 1, 31)
    months = sorted(parse_field(month_field, 1, 12, names=month_names))
    dow_set = parse_field(dow_field, 0, 6, names=dow_names, is_dow=True)

    dom_restricted = dom_field != "*" and not dom_field.startswith("*/")
    dow_restricted = dow_field != "*" and not dow_field.startswith("*/")
    use_or = dom_restricted and dow_restricted

    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        return None

    try:
        limit = after.replace(year=after.year + 8)
    except ValueError:
        if after.year + 8 > 9999:
            limit = datetime.max
        else:
            limit = after.replace(year=after.year + 8, month=2, day=28)

    if start > limit:
        return None

    for year in range(start.year, limit.year + 1):
        for month in months:
            if year == start.year and month < start.month:
                continue
            if year == limit.year and month > limit.month:
                break

            first_py_wd, last_day = calendar.monthrange(year, month)
            first_cron_dow = (first_py_wd + 1) % 7

            d_start = start.day if (year == start.year and month == start.month) else 1
            d_end = min(last_day, limit.day) if (year == limit.year and month == limit.month) else last_day

            for day in range(d_start, d_end + 1):
                dom_match = (day == last_day) if dom_is_last else (day in dom_set)
                dow_match = ((first_cron_dow + day - 1) % 7) in dow_set
                if not ((dom_match or dow_match) if use_or else (dom_match and dow_match)):
                    continue

                if year == start.year and month == start.month and day == start.day:
                    for h in hours:
                        if h < start.hour:
                            continue
                        if h == start.hour:
                            for m in minutes:
                                if m >= start.minute:
                                    cand = datetime(year, month, day, h, m)
                                    return cand if cand <= limit else None
                        else:
                            cand = datetime(year, month, day, h, minutes[0])
                            return cand if cand <= limit else None
                else:
                    cand = datetime(year, month, day, hours[0], minutes[0])
                    return cand if cand <= limit else None

    return None
