def next_run(expr, after):
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")
    if not isinstance(after, datetime) or after.tzinfo is not None:
        raise ValueError("after must be a naive datetime")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    month_names = {
        "jan": 1,
        "feb": 2,
        "mar": 3,
        "apr": 4,
        "may": 5,
        "jun": 6,
        "jul": 7,
        "aug": 8,
        "sep": 9,
        "oct": 10,
        "nov": 11,
        "dec": 12,
    }
    dow_names = {
        "sun": 0,
        "mon": 1,
        "tue": 2,
        "wed": 3,
        "thu": 4,
        "fri": 5,
        "sat": 6,
    }

    def parse_val(s, min_val, max_val, names):
        s_lower = s.lower()
        if names and s_lower in names:
            return names[s_lower]
        if not s.isdigit():
            raise ValueError(f"Invalid value: {s}")
        val = int(s)
        if val < min_val or val > max_val:
            raise ValueError(f"Value out of range: {val}")
        return val

    def parse_step(s):
        if not s.isdigit():
            raise ValueError(f"Invalid step: {s}")
        step = int(s)
        if step <= 0:
            raise ValueError(f"Step must be positive: {step}")
        return step

    def get_range(start, end, min_val, max_val, is_dow):
        if start <= end:
            return list(range(start, end + 1))
        seq = []
        curr = start
        while True:
            seq.append(curr)
            if curr == end or (is_dow and curr % 7 == end % 7):
                break
            if is_dow:
                if curr == 6:
                    curr = 0
                elif curr == 7:
                    curr = 1
                else:
                    curr = (curr + 1) % 7
            else:
                curr += 1
                if curr > max_val:
                    curr = min_val
        return seq

    def parse_field(field_str, min_val, max_val, names, is_dow):
        items = field_str.split(",")
        allowed = set()
        for item in items:
            if not item:
                raise ValueError("Empty item in field")
            if "/" in item:
                parts = item.split("/")
                if len(parts) != 2:
                    raise ValueError(f"Invalid step item: {item}")
                target_str, step_str = parts
                step = parse_step(step_str)
                if target_str == "*":
                    seq = list(range(min_val, max_val + 1))[::step]
                elif "-" in target_str:
                    r_parts = target_str.split("-")
                    if len(r_parts) != 2:
                        raise ValueError(f"Invalid range in step: {target_str}")
                    start = parse_val(r_parts[0], min_val, max_val, names)
                    end = parse_val(r_parts[1], min_val, max_val, names)
                    seq = get_range(start, end, min_val, max_val, is_dow)[
                        ::step
                    ]
                else:
                    start = parse_val(target_str, min_val, max_val, names)
                    seq = list(range(start, max_val + 1))[::step]
            else:
                if item == "*":
                    seq = list(range(min_val, max_val + 1))
                elif "-" in item:
                    r_parts = item.split("-")
                    if len(r_parts) != 2:
                        raise ValueError(f"Invalid range: {item}")
                    start = parse_val(r_parts[0], min_val, max_val, names)
                    end = parse_val(r_parts[1], min_val, max_val, names)
                    seq = get_range(start, end, min_val, max_val, is_dow)
                else:
                    val = parse_val(item, min_val, max_val, names)
                    seq = [val]
            allowed.update(seq)
        return allowed

    minutes_allowed = parse_field(fields[0], 0, 59, None, False)
    hours_allowed = parse_field(fields[1], 0, 23, None, False)

    dom_str = fields[2]
    if dom_str.upper() == "L":
        dom_is_L = True
        dom_allowed = None
    else:
        dom_is_L = False
        dom_allowed = parse_field(dom_str, 1, 31, None, False)

    months_allowed = parse_field(fields[3], 1, 12, month_names, False)

    dow_str = fields[4]
    dow_allowed = parse_field(dow_str, 0, 7, dow_names, True)
    if 7 in dow_allowed:
        dow_allowed.add(0)
    if 0 in dow_allowed:
        dow_allowed.add(7)

    dom_restricted = not (dom_str == "*" or dom_str.startswith("*/"))
    dow_restricted = not (dow_str == "*" or dow_str.startswith("*/"))

    try:
        limit = after.replace(year=after.year + 8)
    except ValueError:
        limit = datetime(
            after.year + 8,
            2,
            28,
            after.hour,
            after.minute,
            after.second,
            after.microsecond,
        )

    curr = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    while True:
        if curr > limit:
            return None

        if curr.month not in months_allowed:
            next_months = [m for m in months_allowed if m > curr.month]
            if next_months:
                curr = datetime(curr.year, min(next_months), 1, 0, 0)
            else:
                curr = datetime(curr.year + 1, min(months_allowed), 1, 0, 0)
            continue

        if curr.month == 12:
            days_in_month = 31
        else:
            days_in_month = (
                datetime(curr.year, curr.month + 1, 1) - timedelta(days=1)
            ).day

        if curr.day > days_in_month:
            curr = datetime(
                curr.year, curr.month, days_in_month, 0, 0
            ) + timedelta(days=1)
            continue

        if dom_is_L:
            dom_matches = curr.day == days_in_month
        else:
            dom_matches = curr.day in dom_allowed

        cron_dow = (curr.weekday() + 1) % 7
        dow_matches = cron_dow in dow_allowed

        if dom_restricted and dow_restricted:
            day_matches = dom_matches or dow_matches
        else:
            day_matches = dom_matches and dow_matches

        if not day_matches:
            curr = datetime(
                curr.year, curr.month, curr.day, 0, 0
            ) + timedelta(days=1)
            continue

        if curr.hour not in hours_allowed:
            next_hours = [h for h in hours_allowed if h > curr.hour]
            if next_hours:
                curr = datetime(
                    curr.year, curr.month, curr.day, min(next_hours), 0
                )
            else:
                curr = datetime(
                    curr.year, curr.month, curr.day, 0, 0
                ) + timedelta(days=1)
            continue

        if curr.minute not in minutes_allowed:
            next_minutes = [m for m in minutes_allowed if m > curr.minute]
            if next_minutes:
                curr = curr.replace(minute=min(next_minutes))
            else:
                curr = datetime(
                    curr.year, curr.month, curr.day, curr.hour, 0
                ) + timedelta(hours=1)
            continue

        return curr
