        if h_next is None:
            d += 1
            h = hours[0]
            mi = minutes[0]
            continue
        if h_next != h:
            h = h_next
            mi = minutes[0]

        mi_next = next((x for x in minutes if x >= mi), None)
        if mi_next is None:
            h += 1
            mi = minutes[0]
            continue

        cand = datetime(y, m, d, h, mi_next)
        if cand > limit:
